            output.Add("circle " + circle.number + " center " + circle.cell.x + " " + circle.cell.y +
                       " radius " + circle.cell.r + " votes " + circle.cell.votes + " points " +
                       circle.cell.total + " gap " + circle.gap + " arcs " + circle.arcs + " pixels " +
